from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import issue_credit_note
from ledgerly.models import Invoice, LineItem
from ledgerly.errors import BillingError

def inv(status="issued", total="50.00"):
    return Invoice("inv_1","cus_1",lines=[LineItem("Seat",1,Decimal(total))],status=status)

# basic
print(issue_credit_note(inv(), Decimal("10.00"), "goodwill"))
# zero/negative
for a in ["0", "-1"]:
    try: issue_credit_note(inv(), a, "x")
    except BillingError as e: print("err", e.code)
# exceeds
try: issue_credit_note(inv(), "60", "x")
except BillingError as e: print("err", e.code)
# wrong status
try: issue_credit_note(inv("draft"), "10", "x")
except BillingError as e: print("err", e.code, e.message)
# approval
try: issue_credit_note(inv(total="1000"), "600", "x")
except BillingError as e: print("err", e.code)
print(issue_credit_note(inv(total="1000"), "600", "x", approved_by="mgr"))
# idempotency
audit.clear()
a = issue_credit_note(inv(), "10", "x", idempotency_key="k1")
b = issue_credit_note(inv(), "10", "x", idempotency_key="k1")
print(a==b, len(audit.events("credit_note_issued")))
EOF"}

